arc_random_seed_int.method.java_expr:
public static int randomSeed(long seed, int min, int max){
        seedr.setSeed(seed);
        if(isPowerOfTwo(max)){
            seedr.nextInt();
        }
        return seedr.nextInt(max - min + 1) + min;
    }

